using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;using Abyss.Story;
public static class VoyageFlowCheck {
 static Stack<IEnumerator> work;static string report;static double deadline;
 public static void Begin(){report="Current flow boundary integration checks (runtime-only accelerated purification and chapter completion setup)\n";work=new();work.Push(Run());deadline=EditorApplication.timeSinceStartup+100;EditorApplication.update+=Tick;}
 static void Tick(){EditorApplication.QueuePlayerLoopUpdate();try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Timed out");if(work.Count==0){EditorApplication.update-=Tick;return;}var e=work.Peek();if(!e.MoveNext()){work.Pop();return;}if(e.Current is IEnumerator child)work.Push(child);else if(e.Current is AsyncOperation op)work.Push(Op(op));}catch(Exception e){report+="FAIL "+e;File.WriteAllText("Tools/MenuPortraitUpdate/flow-check.txt",report);EditorApplication.update-=Tick;}}
 static IEnumerator Op(AsyncOperation op){while(!op.isDone)yield return null;}
 static IEnumerator Wait(float s){double until=EditorApplication.timeSinceStartup+s;while(EditorApplication.timeSinceStartup<until)yield return null;}
 static void Check(bool ok,string text){report+=(ok?"PASS ":"FAIL ")+text+"\n";File.WriteAllText("Tools/MenuPortraitUpdate/flow-check.txt",report);if(!ok)throw new Exception(text);}
 static void SetStage(JourneyStage stage){typeof(StorySceneJourney).GetProperty("Stage").SetValue(StorySceneJourney.Instance,stage);typeof(StorySceneJourney).GetProperty("JourneyStarted").SetValue(StorySceneJourney.Instance,true);}
 static IEnumerator Drain(){for(int i=0;i<80;i++){var d=UnityEngine.Object.FindFirstObjectByType<ShipVisitDialogue>();if(d&&d.UI&&d.UI.Active){if(StorySceneJourney.Instance.Stage==JourneyStage.Finale){ScreenCapture.CaptureScreenshot("Tools/MenuPortraitUpdate/flag.png");yield return Wait(.2f);}d.UI.Advance();}yield return null;}}
 static IEnumerator FinishShip(JourneyStage stage,JourneyStage next){SetStage(stage);Time.timeScale=1;yield return SceneManager.LoadSceneAsync(StorySceneJourney.ShipPath);yield return Wait(.4f);yield return Drain();var ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();var water=ship.GetComponent<ShipWaterPurification>();Check(water.NormalizedProgress<.01f,"Fresh water on "+stage);
 if(stage==JourneyStage.SharkBattle){ScreenCapture.CaptureScreenshot("Tools/MenuPortraitUpdate/harbor.png");yield return Wait(.15f);var ui=UnityEngine.Object.FindFirstObjectByType<ShipUIManager>();Time.timeScale=0;typeof(ShipUIManager).GetMethod("ShowLevelUpScreen",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(ui,null);yield return Wait(.2f);ScreenCapture.CaptureScreenshot("Tools/MenuPortraitUpdate/cards.png");yield return Wait(.15f);ui.OnCardClicked(0);}
 ship.enabled=false;water.forwardDistanceForFull=1;water.RestoreProgress(.999f);ship.GetComponent<Rigidbody2D>().linearVelocity=ship.transform.up*10;yield return Wait(.15f);yield return Drain();yield return Wait(.8f);Check(StorySceneJourney.Instance.Stage==next,stage+" at 100% routes to "+next);}
 static IEnumerator Run(){Application.runInBackground=true;
 yield return FinishShip(JourneyStage.ShipBattle,JourneyStage.ThirdUnderwater);yield return Wait(1);var story=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();Check(story.thirdChapter.Started&&story.Complete,"Third underwater chapter starts without first discovery replay");typeof(UnderwaterThirdChapter).GetField("stage",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(story.thirdChapter,ThirdChapterStage.Completed);story.thirdChapter.chapterCompleted.Invoke();yield return Wait(.8f);yield return Drain();Check(StorySceneJourney.Instance.Stage==JourneyStage.SharkBattle&&SceneManager.GetActiveScene().path==StorySceneJourney.ShipPath,"Shark help completion returns to surface");
 yield return FinishShip(JourneyStage.SharkBattle,JourneyStage.WhaleBattle);yield return Drain();yield return FinishShip(JourneyStage.WhaleBattle,JourneyStage.Finale);yield return Drain();Check(UnityEngine.Object.FindFirstObjectByType<VoyageEnding>()&&Time.timeScale==0,"White flag finale safely pauses combat");Check(GameObject.Find("White flag • ending only"),"White flag visible only at ending");ScreenCapture.CaptureScreenshot("Tools/MenuPortraitUpdate/ending.png");yield return Wait(.2f);Check(GameObject.Find("Epilogue"),"Final text and menu/restart controls appear");Time.timeScale=1;yield return SceneManager.LoadSceneAsync("MainMenu");}
}
